from fpdf import FPDF
BG=(15,23,42); FG=(226,232,240); ACCENT=(251,146,60); MUTED=(148,163,184); CODE_BG=(30,41,59); GREEN=(52,211,153)
class DarkPDF(FPDF):
    def header(self):
        self.set_fill_color(*BG); self.rect(0,0,self.w,self.h,"F"); self.set_y(10)
        self.set_font("Helvetica","I",8); self.set_text_color(*MUTED)
        self.cell(0,5,"AutoSaaS AI - Code Documentation",align="R"); self.ln(5)
    def footer(self):
        self.set_y(-10); self.set_font("Helvetica","I",8); self.set_text_color(*MUTED)
        self.cell(0,5,f"Page {self.page_no()}",align="C")
pdf=DarkPDF(); pdf.set_auto_page_break(auto=True,margin=15); pdf.add_page()
def title(t):
    pdf.set_font("Helvetica","B",22); pdf.set_text_color(*ACCENT); pdf.ln(8)
    pdf.cell(0,12,t,new_x="LMARGIN",new_y="NEXT"); pdf.ln(2)
def h1(t):
    pdf.set_font("Helvetica","B",16); pdf.set_text_color(*ACCENT); pdf.ln(4)
    pdf.cell(0,10,t,new_x="LMARGIN",new_y="NEXT"); pdf.set_text_color(*FG); pdf.set_font("Helvetica",size=11)
def h2(t):
    pdf.set_font("Helvetica","B",13); pdf.set_text_color(*GREEN); pdf.ln(2)
    pdf.cell(0,8,t,new_x="LMARGIN",new_y="NEXT"); pdf.set_text_color(*FG); pdf.set_font("Helvetica",size=11)
def para(t):
    pdf.set_text_color(*FG); pdf.set_font("Helvetica",size=11)
    pdf.multi_cell(190,6,t,new_x="LMARGIN",new_y="NEXT")
def bullet(t,ind=5):
    pdf.set_text_color(*FG); pdf.set_font("Helvetica",size=11)
    pdf.cell(ind,5,"",new_x="RIGHT",new_y="TOP")
    pdf.multi_cell(190-ind,5,"- "+t,new_x="LMARGIN",new_y="NEXT")
def code(t):
    pdf.set_fill_color(*CODE_BG); pdf.set_font("Courier",size=9); pdf.set_text_color(*GREEN)
    for l in t.split(chr(10)): pdf.cell(190,5,"  "+l,fill=True,new_x="LMARGIN",new_y="NEXT")
    pdf.set_font("Helvetica",size=11); pdf.set_text_color(*FG); pdf.ln(2)
def diagram(t):
    pdf.set_fill_color(*CODE_BG); pdf.set_font("Courier",size=8); pdf.set_text_color(*MUTED)
    for l in t.split(chr(10)): pdf.cell(190,4.5,l,fill=True,new_x="LMARGIN",new_y="NEXT")
    pdf.set_font("Helvetica",size=11); pdf.set_text_color(*FG); pdf.ln(2)
